u_ai_tool.u_parameters:
{
  "type": "object",
  "properties": {
    "title": {
      "type": "string",
      "description": "Clear, searchable title for the KB article"
    },
    "content": {
      "type": "string",
      "description": "Full article content with symptoms, cause, resolution, prevention sections"
    },
    "category": {
      "type": "string",
      "description": "KB category (e.g., IT Support, HR, Facilities)"
    },
    "article_type": {
      "type": "string",
      "enum": [
        "FAQ",
        "How-To",
        "Troubleshooting",
        "Reference"
      ],
      "description": "Type of knowledge article"
    },
    "visibility": {
      "type": "string",
      "enum": [
        "internal",
        "self_service"
      ],
      "description": "Who can see this article"
    },
    "source_incident": {
      "type": "string",
      "description": "Incident number that prompted this article (optional)"
    },
    "keywords": {
      "type": "string",
      "description": "Comma-separated keywords for searchability"
    }
  },
  "required": [
    "title",
    "content",
    "category",
    "article_type"
  ]
}

u_ai_tool.u_script:
(function(args, userId) {
    // Helper function to convert markdown to HTML
    var markdownToHtml = function(text) {
        if (!text) return '';
        var html = text;

        // Convert headers (### Header -> <h3>Header</h3>)
        html = html.replace(/^### (.*$)/gim, '<h3>$1</h3>');
        html = html.replace(/^## (.*$)/gim, '<h2>$1</h2>');
        html = html.replace(/^# (.*$)/gim, '<h1>$1</h1>');

        // Convert bold (**text** -> <strong>text</strong>)
        html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

        // Convert italic (*text* -> <em>text</em>)
        html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');

        // Convert line breaks to <br> or <p> tags
        var paragraphs = html.split('\n\n');
        var wrappedParagraphs = [];
        for (var i = 0; i < paragraphs.length; i++) {
            var para = paragraphs[i].trim();
            if (para) {
                // Check if it's already a header
                if (!para.match(/^<h[1-6]>/)) {
                    // Convert single line breaks to <br>
                    para = para.replace(/\n/g, '<br>');
                    wrappedParagraphs.push('<p>' + para + '</p>');
                } else {
                    wrappedParagraphs.push(para);
                }
            }
        }

        return wrappedParagraphs.join('\n');
    };

    // Validate required fields
    if (!args.title || !args.content || !args.category || !args.article_type) {
        return {
            success: false,
            error: 'Missing required fields: title, content, category, article_type'
        };
    }

    // Create the KB article
    var kbGR = new GlideRecord('kb_knowledge');
    kbGR.initialize();

    // Set basic fields
    kbGR.short_description = args.title;

    // Convert content to HTML
    var htmlContent = markdownToHtml(args.content);
    kbGR.text = htmlContent;

    kbGR.article_type = args.article_type || 'How-To';
    kbGR.workflow_state = 'draft'; // Start in draft for review

    // Set visibility
    if (args.visibility === 'self_service') {
        kbGR.u_viewable_by = 'everyone';
    } else {
        kbGR.u_viewable_by = 'internal';
    }

    // Set category if valid
    if (args.category) {
        var catGR = new GlideRecord('kb_category');
        catGR.addQuery('label', args.category);
        catGR.setLimit(1);
        catGR.query();
        if (catGR.next()) {
            kbGR.kb_category = catGR.getUniqueValue();
        }
    }

    // Set keywords for search
    if (args.keywords) {
        kbGR.meta = args.keywords;
    }

    // Set author to requesting user
    kbGR.author = userId;

    // Insert the record
    var kbSysId = kbGR.insert();

    if (!kbSysId) {
        return {
            success: false,
            error: 'Failed to create KB article'
        };
    }

    // Link to source incident if provided
    if (args.source_incident) {
        var incGR = new GlideRecord('incident');
        incGR.addQuery('number', args.source_incident);
        incGR.setLimit(1);
        incGR.query();
        if (incGR.next()) {
            // Add work note to incident
            incGR.work_notes = 'KB article created from this incident: ' + kbGR.number;
            incGR.update();
        }
    }

    return {
        success: true,
        kb_number: kbGR.number.toString(),
        kb_sys_id: kbSysId,
        title: args.title,
        state: 'draft',
        message: 'KB article ' + kbGR.number + ' created successfully in draft state. Please review and publish.'
    };
})(args, userId);
